"""Original dialysis chapter: peritoneal therapy and integrated management."""
from create_dialysis import rows,q,AK,HD,VA,PD,PG
from qbank_authoring import ref,finalize
UK=ref('Renal Association Clinical Practice Guideline on Haemodialysis, 2019','https://pmc.ncbi.nlm.nih.gov/articles/PMC6798406/')
for item in rows:
 if any(t in item['question'] for t in ['carpal tunnel','new dialyzer','intradialytic hypotension']):item['references'].append(UK)

q('Which combination satisfies the usual ISPD diagnostic definition of PD-associated peritonitis?', 'At least two of compatible symptoms, inflammatory effluent and a positive effluent culture',[
 ('A positive culture is mandatory in every episode','Culture-negative peritonitis can meet the other criteria.'),('Cloudy effluent alone proves bacterial peritonitis','Cloudiness has alternative causes and requires investigation.'),('Fever plus a positive urine culture is sufficient','These do not establish peritoneal infection.')],
 'Use a combined clinical and effluent definition', '**Inflammatory effluent usually means WBC above 100/µL with more than 50% neutrophils after a dwell of at least two hours.**',['Compatible symptoms include abdominal pain or cloudy effluent.','Short automated dwells require particular attention to neutrophil proportion.'], '**Sample before antibiotics without delaying treatment.**',['Request cell count, differential and culture.','Consider peritonitis even if abdominal pain occurs with initially clear effluent.'],[['Clinical criterion','Pain/cloudy effluent'],['Cell criterion','Inflammatory neutrophilic fluid'],['Microbiology','Positive culture when present']],[PD])
q('A stable PD patient has abdominal pain and cloudy effluent. What is the best initial antimicrobial strategy after appropriate sampling?', 'Prompt empiric coverage of gram-positive and gram-negative organisms, generally by the intraperitoneal route',[
 ('Wait for final cultures before starting any antibiotic','Delay can worsen outcome.'),('Treat only gram-positive organisms in every unit','Initial gram-negative coverage is also needed.'),('Use oral antifungal monotherapy for every first episode','This does not cover typical bacterial causes.')],
 'Early treatment and adequate spectrum matter', '**Empiric selection reflects local resistance and allergy.**',['Intraperitoneal administration provides local drug exposure when feasible.','Systemic sepsis requires appropriate systemic treatment and stabilization.'], '**Narrow treatment once organism and response are known.**',['Review dose, dwell and residual clearance.','Evaluate catheter and technique as potential contributors.'],[['Initial spectrum','Gram-positive plus gram-negative'],['Stable patient route','Usually intraperitoneal'],['Sepsis','Systemic emergency care']],[PD],'clinical_scenario')
q('Yeast is identified in PD effluent from a symptomatic patient. Which strategy is recommended?', 'Prompt PD catheter removal plus appropriate antifungal treatment',[
 ('Preserve the catheter and use antibacterial therapy alone','This leaves fungal biofilm and provides inappropriate coverage.'),('Observe for spontaneous clearance without treatment','Fungal peritonitis carries substantial morbidity and mortality.'),('Use a single antifungal dose then immediately reinsert a catheter','This is inadequate treatment and premature replacement.')],
 'Fungal infection changes catheter management', '**Biofilm makes catheter retention hazardous.**',['Identify the organism and select an active antifungal.','Alternative KRT may be required during treatment.'], '**Continue antifungal treatment after removal.**',['ISPD recommends at least two weeks after removal, with longer courses in selected cases.','Reinsertion requires recovery and specialist assessment.'],[['Key intervention','Remove catheter'],['Drug','Organism-directed antifungal'],['Duration','At least two weeks after removal']],[PD],'clinical_scenario')
q('On day five of appropriate treatment for PD peritonitis, effluent remains mildly cloudy but WBC is steadily falling and the patient is improving. Which interpretation best reflects ISPD 2022?', 'Continued observation can be appropriate rather than mandatory removal solely because day five has been reached',[
 ('Every catheter must be removed on day five regardless of response','The guideline permits a response-based exception.'),('Clinical improvement means antibiotics can be stopped immediately','An adequate organism-specific course is still required.'),('Persistent severe illness should also be observed indefinitely','Nonresponse or deterioration calls for source control.')],
 'Distinguish delayed response from treatment failure', '**Refractory infection generally requires catheter removal.**',['A falling cell count toward normal can justify observation beyond five days.','Symptoms, organism and complications modify the decision.'], '**Do not prolong ineffective therapy in a deteriorating patient.**',['Recheck susceptibility and dosing.','Consider secondary abdominal pathology or unusual organisms.'],[['Improving trend','Observation may be reasonable'],['Persistent nonresponse','Source-control assessment'],['Day count alone','Insufficient decision rule']],[PD],'clinical_scenario')
q('Pseudomonas is isolated in PD peritonitis. Which antimicrobial principle is generally recommended?', 'Two susceptible antibiotics with different mechanisms, usually for three weeks',[
 ('One inactive oral agent for three days','Neither spectrum nor duration is adequate.'),('Routine antifungal monotherapy','This is a bacterial infection.'),('No catheter assessment even if a matching tunnel infection is present','Concurrent catheter infection changes source-control needs.')],
 'Pseudomonas peritonitis has a substantial treatment-failure risk', '**Use two active agents with different mechanisms.**',['Selection depends on susceptibility and safe delivery.','A matching exit-site or tunnel infection strengthens the case for removal.'], '**Review response early.**',['Failure to improve prompts catheter removal assessment rather than endless antibiotic escalation.','Plan temporary modality support if removal is needed.'],[['Therapy','Two active mechanisms'],['Typical duration','Three weeks'],['Catheter infection','Assess removal']],[PD])
q('A PD patient has severe abdominal pain, hypotension and multiple enteric organisms in effluent. What additional priority is required?', 'Urgent evaluation for an intra-abdominal surgical source',[
 ('Assume routine touch contamination explains every polymicrobial episode','Enteric organisms with systemic illness raise concern for bowel pathology.'),('Treat only the exit site without imaging or surgical assessment','This misses a possible abdominal emergency.'),('Exclude bowel disease because a PD catheter is present','PD does not protect against perforation or ischemia.')],
 'Not all PD peritonitis originates from catheter handling', '**Enteric polymicrobial infection can signal perforation or another abdominal source.**',['Hemodynamic instability increases urgency.','Broad antimicrobial therapy should accompany source evaluation.'], '**Arrange imaging and surgical input when indicated.**',['Do not let the familiar PD diagnosis delay source control.','Catheter decisions depend on the final cause and operative findings.'],[['Organisms','Multiple enteric species'],['Clinical severity','Shock/peritoneal signs'],['Priority','Abdominal source control']],[PD],'clinical_scenario')
q('Why is antifungal prophylaxis considered when a PD patient receives an antibiotic course?', 'Antibiotic exposure increases the risk of subsequent fungal peritonitis',[
 ('It replaces treatment of the bacterial infection','Antifungal prophylaxis does not treat the bacterial cause.'),('It removes all need for technique training','Training and infection prevention remain necessary.'),('Every antifungal has identical interaction and resistance profiles','Drug selection requires individual review.')],
 'Prevent a predictable secondary infection', '**ISPD recommends antifungal prophylaxis during antibiotic courses for PD patients.**',['Nystatin or fluconazole may be used according to protocol and availability.','Interactions and contraindications must be checked.'], '**Keep the prophylactic purpose clear.**',['Suspected established fungal peritonitis requires treatment and catheter assessment.','A prophylactic course is not adequate therapy for proven fungal disease.'],[['Trigger','Antibiotic course'],['Purpose','Reduce fungal peritonitis risk'],['Choice','Protocol and patient factors']],[PD])
q('A PD patient has purulent discharge at the catheter exit site without abdominal symptoms. Which finding best establishes an exit-site infection?', 'Purulent discharge, with or without surrounding erythema',[
 ('Erythema alone in every recently inserted catheter','Erythema alone can reflect irritation or trauma.'),('A positive swab from normal skin without clinical findings','Colonization is not equivalent to infection.'),('A single low ultrafiltration measurement','This does not diagnose exit-site infection.')],
 'Clinical infection differs from colonization', '**Purulence is central to the exit-site infection definition.**',['Culture helps target therapy.','Tunnel tenderness or swelling suggests deeper involvement.'], '**Assess the tunnel and monitor response.**',['Use organism-directed treatment under the current catheter-infection guidance.','Concurrent peritonitis from the same organism may require catheter removal.'],[['Exit-site infection','Purulent discharge'],['Tunnel disease','Deeper tract involvement'],['Colonization','Culture without clinical infection']],[PG],'clinical_scenario')
q('What is the main purpose of a peritoneal equilibration test?', 'Characterizing peritoneal solute transport to help individualize the PD prescription',[
 ('Measuring native kidney GFR directly','The test assesses peritoneal transport rather than native filtration.'),('Diagnosing every cause of abdominal pain','This is not a general abdominal diagnostic test.'),('Proving infection from the dialysate glucose alone','Peritonitis requires clinical and inflammatory assessment.')],
 'Membrane transport affects optimal dwell length', '**The dialysate-to-plasma creatinine ratio helps classify solute transport.**',['Fast transport causes earlier glucose gradient dissipation.','Ultrafiltration assessment adds information beyond solute equilibration.'], '**Interpret results alongside volume and residual function.**',['Mechanical drainage problems may mimic membrane failure.','Do not use a transport label in isolation.'],[['PET','Peritoneal transport'],['Fast transport','Rapid gradient loss'],['Prescription','Dwell and osmotic-agent adjustment']],[PG])
q('A fast peritoneal transporter has poor ultrafiltration during long glucose dwells. Which prescription change is mechanistically appropriate?', 'Shorter glucose dwells with consideration of icodextrin for the long dwell',[
 ('Lengthen every glucose dwell indefinitely','The glucose osmotic gradient may dissipate and permit reabsorption.'),('Eliminate all assessment of residual urine','Residual clearance and fluid removal still contribute.'),('Treat as bacterial peritonitis solely from the transport result','A PET pattern does not establish infection.')],
 'Match dwell time to membrane behavior', '**Fast solute transfer can rapidly dissipate a glucose gradient.**',['Automated short cycles may improve glucose-dwell ultrafiltration.','Icodextrin provides sustained colloid osmotic action for a long dwell.'], '**Check drainage and fluid intake as well.**',['Peritonitis can transiently alter transport.','Review net daily fluid balance and sodium removal.'],[['Fast transport','Rapid equilibration'],['Short glucose dwell','Preserves early gradient'],['Long dwell','Consider icodextrin']],[PG],'clinical_scenario')
q('Which mechanism accounts for early sodium sieving during a hypertonic glucose PD dwell?', 'Aquaporin-mediated free-water transport dilutes dialysate sodium',[
 ('Active secretion of sodium by the peritoneum','The phenomenon reflects water movement rather than a sodium pump.'),('Complete blockade of all small-pore transport','Small pores continue to function.'),('A falsely elevated serum sodium from urea','Urea does not produce this specific dialysate pattern.')],
 'Water and sodium do not cross identically', '**Aquaporin-1 channels permit solute-free water movement.**',['Early water influx can lower dialysate sodium concentration.','Reduced sodium sieving can suggest impaired osmotic water transport.'], '**Use an appropriate standardized test.**',['Consider both water-channel and small-pore pathways.','Interpret membrane function with clinical ultrafiltration.'],[['Aquaporins','Free water'],['Small pores','Water plus small solutes'],['Sodium dip','Early dilution']],[PG])
q('A four-hour standardized PET with 4.25% dextrose yields net ultrafiltration below 400 mL. What does this suggest?', 'Insufficient ultrafiltration capacity requiring clinical and mechanical evaluation',[
 ('Automatically irreversible membrane failure requiring immediate permanent transfer','Mechanical problems, leaks and reversible factors must be excluded.'),('Proof of normal ultrafiltration in every adult','This is below the guideline test threshold.'),('A diagnosis of glomerulonephritis','The measurement concerns peritoneal function.')],
 'A threshold identifies a problem, not its cause', '**Low test ultrafiltration can reflect rapid gradient loss or intrinsic membrane dysfunction.**',['Leaks and poor drainage are alternative explanations.','Daily fluid status determines the practical consequence.'], '**Investigate before changing long-term modality.**',['Review catheter function and prescription.','Assess the transport profile and the patient’s goals.'],[['Test','Four-hour hypertonic PET'],['Low net UF','Below 400 mL'],['Next step','Determine mechanism']],[PG])
q('Which assessment best reflects high-quality goal-directed PD?', 'Symptoms, volume status, nutrition, residual function and measured clearance considered together',[
 ('A weekly urea clearance value alone regardless of symptoms','A number alone does not establish patient-centered adequacy.'),('Urine volume alone without clearance or volume assessment','Volume is not equivalent to residual solute clearance.'),('Absence of peritonitis alone','Infection control is important but does not define overall adequacy.')],
 'Adequacy is a multidimensional clinical outcome', '**A technically acceptable small-solute clearance can coexist with fluid overload or poor wellbeing.**',['PD burden and patient goals matter.','Nutritional decline requires assessment rather than automatic attribution to uremia.'], '**Individualize and reassess the prescription.**',['Include home feasibility and treatment support.','Address reversible non-dialysis causes of symptoms.'],[['Clinical','Symptoms and volume'],['Biochemical','Clearance and electrolytes'],['Personal','Goals and burden']],[PG])
q('A PD patient develops poor outflow but inflow is relatively preserved. Abdominal examination suggests constipation. Which initial approach is reasonable?', 'Evaluate and treat constipation while checking catheter position and other mechanical causes',[
 ('Assume permanent membrane failure before checking drainage','Outflow obstruction can be mechanical.'),('Increase glucose concentration as the only response','This does not correct catheter obstruction.'),('Diagnose fungal peritonitis without effluent investigation','Poor flow alone is not diagnostic of infection.')],
 'Mechanical problems can imitate inadequate dialysis', '**Constipation can impair catheter drainage.**',['Migration, kinking and fibrin are additional possibilities.','Pain or cloudy effluent calls for concurrent infection assessment.'], '**Use a stepwise catheter-function evaluation.**',['Review position and recent bowel habits.','Escalate to imaging or procedural correction when needed.'],[['Inflow preserved','Consider outflow obstruction'],['Constipation','Treatable contributor'],['Persistent dysfunction','Further mechanical assessment']],[PG],'clinical_scenario')
q('Why does a patient using icodextrin need a compatible glucose-monitoring system?', 'Some nonspecific glucose assays misread metabolites as glucose and can trigger dangerous excess insulin',[
 ('Icodextrin always causes true extreme hyperglycemia','The issue can be assay interference rather than actual glucose elevation.'),('All glucose meters are equally safe with icodextrin','Compatibility varies by assay technology.'),('Laboratory glucose testing becomes impossible','Specific validated methods remain available.')],
 'An assay artifact can become a treatment emergency', '**Maltose-related interference can produce falsely high readings with incompatible systems.**',['Inappropriate insulin can cause severe hypoglycemia.','Hospitals and patients must know the PD solution used.'], '**Verify manufacturer compatibility rather than guessing from meter brand.**',['Use a glucose-specific validated method.','Investigate discordance between symptoms and bedside readings.'],[['Exposure','Icodextrin metabolites'],['Error','False high glucose'],['Harm','Excess insulin/hypoglycemia']],[PG])
q('A long-term PD patient develops recurrent obstruction, weight loss and CT evidence of bowel encapsulation with peritoneal thickening. Which complication is most likely?', 'Encapsulating peritoneal sclerosis',[
 ('Isolated uncomplicated exit-site infection','This does not explain bowel encapsulation.'),('Dialysis disequilibrium syndrome','This is an acute neurological disorder.'),('Simple glucose absorption without structural disease','It does not explain obstructive encapsulation.')],
 'A rare structural complication can threaten nutrition and bowel function', '**EPS involves inflammatory and fibrotic encapsulation of bowel.**',['Long PD exposure is an important context.','Symptoms can arise after stopping PD as well.'], '**Seek specialist multidisciplinary care.**',['Provide nutritional support and assess obstruction.','Surgical and medical strategies require individualized expert selection.'],[['Presentation','Obstruction/weight loss'],['Imaging','Encapsulation and thickening'],['Care','Specialist multidisciplinary approach']],[PG],'clinical_scenario')
q('Which property makes an ingested toxin more amenable to conventional hemodialysis?', 'Low molecular weight, low protein binding and a small volume of distribution',[
 ('Very high tissue distribution and irreversible intracellular binding','These limit access to circulating toxin.'),('Near-complete protein binding with minimal free fraction in all circumstances','This usually impairs conventional clearance, although poisoning kinetics can change.'),('Large molecular size beyond membrane permeability','This limits conventional diffusive removal.')],
 'Dialyzability depends on distribution as well as membrane clearance', '**Only toxin available to the extracorporeal circuit can be removed directly.**',['Small free molecules are generally easier to clear.','Toxic exposure can alter binding and saturation.'], '**Use toxin-specific evidence for the actual decision.**',['Clinical severity, endogenous clearance and rebound also matter.','Do not infer an indication solely from a generic physicochemical rule.'],[['Free small molecule','More accessible'],['Large tissue reservoir','Limits removal'],['Decision','Toxin-specific guidance']],[AK])
q('When stopping KRT after AKI, which assessment is most useful?', 'Evidence that native kidney function can meet current fluid and metabolic needs',[
 ('A normal creatinine immediately after dialysis alone','Extracorporeal clearance temporarily lowers creatinine.'),('Any diuretic-induced urine output proves full recovery','Urine volume does not establish sufficient solute clearance.'),('A fixed calendar duration regardless of recovery','The need for support changes with the clinical course.')],
 'Recovery is a functional capacity assessment', '**Urine output, interdialytic biochemistry and measured clearance can inform a trial off therapy.**',['Fluid inputs and catabolic burden change the required capacity.','A falling creatinine must be interpreted relative to recent dialysis.'], '**Monitor closely during withdrawal.**',['Reintroduce support if urgent indications recur.','Arrange follow-up because AKI survivors remain at risk of CKD.'],[['Recovery evidence','Native clearance and volume handling'],['Post-dialysis creatinine','Potentially misleading'],['Trial off','Requires surveillance']],[AK])
q('Which symptom is a particularly important reason to assess a high-flow fistula for a systemic hemodynamic complication?', 'New high-output heart failure with a large access flow contribution',[
 ('Isolated low phosphate without cardiovascular findings','This does not suggest access-related shunting.'),('A localized small bruise that resolves','This is not a systemic shunt complication.'),('A single positive urine dipstick for blood','This is unrelated to high access flow.')],
 'An access is also a circulatory shunt', '**A large arteriovenous flow can increase cardiac output requirements.**',['Heart disease can lower tolerance.','The diagnosis requires clinical and hemodynamic assessment rather than access size alone.'], '**Balance cardiac benefit and dialysis needs.**',['Specialist flow-reduction strategies may preserve usable access.','Assess other common causes of heart failure.'],[['Mechanism','Arteriovenous shunting'],['Consequence','High-output cardiac stress'],['Management','Hemodynamic and access review']],[VA,UK])
q('A suitable patient chooses comprehensive conservative kidney care after informed discussion. Which statement is correct?', 'Active symptom treatment and supportive care continue even without dialysis',[
 ('Conservative care means stopping all medical treatment','It is an active care pathway.'),('Dialysis must be imposed whenever eGFR falls below a single cutoff','Treatment reflects clinical need and informed goals.'),('Palliative support is incompatible with nephrology follow-up','These approaches can be integrated.')],
 'A modality decision includes the option of conservative care', '**Shared decisions consider expected benefit, treatment burden and patient priorities.**',['Conservative care includes volume, anemia and symptom management as appropriate.','Advance care planning and family support can be valuable.'], '**Revisit decisions if circumstances or preferences change.**',['Provide clear information without abandonment.','Document the plan and routes for symptom crises.'],[['Conservative care','Active supportive treatment'],['Decision','Informed individual goals'],['Follow-up','Ongoing reassessment']],[PG,UK])

if __name__=='__main__':finalize('Nephrology',6,'Dialysis and Kidney Replacement Therapy','neph-dialysis',rows,40)
